content:
:root {
  --primary: #4f46e5;
  --primary-hover: #4338ca;
  --bg-color: #f3f4f6;
  --card-bg: #ffffff;
  --text-main: #1f2937;
  --text-muted: #4b5563; /* コントラスト比を向上させるために少し濃く調整 */
  --border-color: #d1d5db;
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-main);
  line-height: 1.5;
}

.app-container {
  max-width: 800px;
  margin: 40px auto;
  padding: 20px;
}

.header {
  text-align: center;
  margin-bottom: 30px;
}

.title {
  font-size: 2rem;
  font-weight: 700;
  color: var(--primary);
}

.converter-card {
  background-color: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
  margin-bottom: 24px;
}

.input-group {
  display: flex;
  gap: 12px;
  margin-bottom: 24px;
}

.input-field {
  flex: 1;
  padding: 12px 16px;
  font-size: 1.1rem;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  outline: none;
  transition: border-color 0.2s;
}

.input-field::placeholder {
  color: var(--text-muted);
  opacity: 1;
}

.input-field:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1);
}

.select-box {
  padding: 12px 16px;
  font-size: 1.1rem;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background-color: #fff;
  outline: none;
  cursor: pointer;
  transition: border-color 0.2s;
}

.select-box:focus {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(79, 70, 229, 0.1);
}

.results-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 16px;
}

.result-item {
  background-color: #f9fafb;
  border: 1px solid #e5e7eb;
  padding: 16px;
  border-radius: 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.result-name {
  font-size: 0.9rem;
  color: var(--text-muted);
  font-weight: 500;
}

.result-value {
  font-size: 1.25rem;
  font-weight: 600;
  color: var(--text-main);
  word-break: break-all;
}

.presets-section {
  background-color: var(--card-bg);
  padding: 24px;
  border-radius: var(--radius);
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06);
}

.preset-title {
  font-size: 1.1rem;
  font-weight: 600;
  margin-bottom: 12px;
  color: var(--text-main);
}

.preset-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.preset-btn {
  padding: 8px 16px;
  background-color: #e0e7ff;
  color: var(--primary);
  border: none;
  border-radius: 6px;
  font-size: 0.95rem;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
}

.preset-btn:hover {
  background-color: #c7d2fe;
}

.preset-btn:active {
  transform: scale(0.98);
}

@media (max-width: 600px) {
  .input-group {
    flex-direction: column;
  }
  .app-container {
    margin: 10px;
    padding: 10px;
  }
}

@media (max-width: 320px) {
  .app-container {
    margin: 4px;
    padding: 6px;
  }
  .title {
    font-size: 1.4rem;
  }
  .converter-card, .presets-section {
    padding: 14px 10px;
  }
  .input-field, .select-box {
    font-size: 0.95rem;
    padding: 10px 12px;
  }
  .result-value {
    font-size: 1.1rem;
  }
  .preset-btn {
    font-size: 0.85rem;
    padding: 6px 10px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

export type Unit = 'mm' | 'cm' | 'm' | 'km' | 'inch' | 'feet' | 'yard';

export interface PresetItem {
  id: string;
  name: string;
  value: number;
  unit: Unit;
  description: string;
}

import { useState } from 'react';
import { Unit, PresetItem } from './types';
import './index.css';

const UNIT_LABELS: Record<Unit, string> = {
  mm: 'ミリメートル (mm)',
  cm: 'センチメートル (cm)',
  m: 'メートル (m)',
  km: 'キロメートル (km)',
  inch: 'インチ (in)',
  feet: 'フィート (ft)',
  yard: 'ヤード (yd)',
};

const PRESETS: PresetItem[] = [
  { id: '1', name: 'A4用紙の長辺', value: 297, unit: 'mm', description: '一般的なコピー用紙' },
  { id: '2', name: 'クレジットカードの横幅', value: 85.6, unit: 'mm', description: 'カードサイズ' },
  { id: '3', name: '100m走', value: 100, unit: 'm', description: '陸上短距離走の距離' },
  { id: '4', name: 'マラソンフルコース', value: 42.195, unit: 'km', description: '伝統的なマラソンの距離' },
  { id: '5', name: '1フィート定規', value: 1, unit: 'feet', description: '約30.48cm' },
  { id: '6', name: 'スマートフォン目安', value: 6.1, unit: 'inch', description: '画面対角線の目安' },
];

export default function App() {
  const [inputValue, setInputValue] = useState<string>('1');
  const [currentUnit, setCurrentUnit] = useState<Unit>('m');

  const numValue = parseFloat(inputValue);
  const isValid = !isNaN(numValue);
  const isNegative = isValid && numValue < 0;

  // mmを基準とした換算レート
  const toMmRates: Record<Unit, number> = {
    mm: 1,
    cm: 10,
    m: 1000,
    km: 1000000,
    inch: 25.4,
    feet: 304.8,
    yard: 914.4,
  };

  // 入力値をmmに変換
  const valueInMm = isValid && !isNegative ? numValue * toMmRates[currentUnit] : 0;

  // 各単位へ変換
  const convert = (targetUnit: Unit): string => {
    if (inputValue.trim() === '') return '数値を入力してください';
    if (!isValid) return '無効な数値です';
    if (isNegative) return '正の数を入力してください';
    const converted = valueInMm / toMmRates[targetUnit];
    if (converted === 0) return '0';
    if (Math.abs(converted) < 0.000001 || Math.abs(converted) >= 1e10) {
      return converted.toExponential(4);
    }
    return parseFloat(converted.toFixed(6)).toString();
  };

  const handlePresetClick = (preset: PresetItem) => {
    setInputValue(preset.value.toString());
    setCurrentUnit(preset.unit);
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">長さ単位変換ツール</h1>
      </header>

      <div className="converter-card">
        <div className="input-group">
          <input
            type="number"
            className="input-field"
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            placeholder="数値を入力..."
          />
          <select
            className="select-box"
            value={currentUnit}
            onChange={(e) => setCurrentUnit(e.target.value as Unit)}
          >
            {(Object.keys(UNIT_LABELS) as Unit[]).map((u) => (
              <option key={u} value={u}>
                {UNIT_LABELS[u]}
              </option>
            ))}
          </select>
        </div>

        {isNegative && (
          <div style={{ color: '#ef4444', fontSize: '0.9rem', marginBottom: '16px', fontWeight: 500 }}>
            ⚠️ 物理的に存在しない負の長さ（マイナス値）は指定できません。0以上の数値を入力してください。
          </div>
        )}

        {!isValid && inputValue.trim() !== '' && (
          <div style={{ color: '#ef4444', fontSize: '0.9rem', marginBottom: '16px', fontWeight: 500 }}>
            ⚠️ 有効な数値を入力してください。
          </div>
        )}

        <div className="results-grid">
          {(Object.keys(UNIT_LABELS) as Unit[]).map((u) => (
            <div className="result-item" key={u}>
              <span className="result-name">{UNIT_LABELS[u]}</span>
              <span className="result-value">
                {convert(u)} {isValid && !isNegative && inputValue.trim() !== '' ? u : ''}
              </span>
            </div>
          ))}
        </div>
      </div>

      <div className="presets-section">
        <h2 className="preset-title">プリセットから選ぶ</h2>
        <div className="preset-buttons">
          {PRESETS.map((preset) => (
            <button
              key={preset.id}
              className="preset-btn"
              onClick={() => handlePresetClick(preset)}
              title={preset.description}
            >
              {preset.name} ({preset.value} {preset.unit})
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}
